contract InvMutTest {
    C c;
    bool rejectPayments;

    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.SetMinSum(0);
        c.Deposit{value: amount}();
        uint256 balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        rejectPayments = true;
        bool reverted;
        try c.Collect(amount) { reverted = false; }
        catch { reverted = true; }
        uint256 balAfter = c.balances(address(this));
        uint ethAfter = address(c).balance;
        rejectPayments = false;
        assert(reverted && balAfter == balBefore && ethAfter == ethBefore);
    }

    receive() external payable {
        if (rejectPayments) revert();
    }
}
